style.css:
@-moz-document domain("roblox.com") {
/* Fondo global */
  html, body {
    background: url("https://i.imgur.com/muxmD5l.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Asegurar que no haya fondos sólidos que tapen */
  #container-main,
  .content,
  .container-main,
  .rbx-body,
  .rbx-main-content,
  .rbx-header {
    background: transparent !important;
  }

  /* Fondo de los bloques centrales con un poquito de transparencia */
  .container-main,
  .content,
  #container-main {
    background: rgba(0,0,0,0.55) !important;
    border-radius: 12px !important;
  }

  /* Botones */
  button,
  .btn-primary {
    background-color: #6a0dad !important;
    border: none !important;
    color: white !important;
  }

  button:hover,
  .btn-primary:hover {
    background-color: #9a4dff !important;
  }

  /* Links */
  a {
    color: #ff4da6 !important;
  }

  a:hover {
    color: #ffffff !important;
    text-shadow: 0 0 5px #ff4da6;
  }

  /* Títulos */
  h1, h2, h3, .title-text {
    font-family: "Poppins", sans-serif !important;
    color: #ffffff !important;
    text-shadow: 0 0 10px #6a0dad;
  }
}
